import { test } from "node:test";
import assert from "node:assert/strict";
import { Store } from "../src/db/store.ts";
import { RotaService } from "../src/oncall/rota.ts";
import { coverageReport, uncovered } from "../src/oncall/coverage.ts";

const now = new Date("2026-11-19T22:00:00Z");

async function setup(shifts: Record<string, string[]>) {
    const db = new Store();
    const rota = new RotaService(db);
    for (const [shiftId, doctors] of Object.entries(shifts)) {
        for (const d of doctors) await rota.join(shiftId, d, now);
    }
    return { db, rota };
}

test("a doctor can leave while a colleague still covers the shift", async () => {
    const { db, rota } = await setup({ "icu-night": ["dr-adeyemi", "dr-brandt"] });
    assert.equal(await rota.leave("icu-night", "dr-adeyemi", now), "left");
    assert.deepEqual(await coverageReport(db, ["icu-night"]), [{ shiftId: "icu-night", onCall: ["dr-brandt"] }]);
});

test("the last doctor on call is refused", async () => {
    const { rota } = await setup({ "icu-night": ["dr-adeyemi"] });
    assert.equal(await rota.leave("icu-night", "dr-adeyemi", now), "refused_last_cover");
});

test("two doctors leaving the same shift at the same moment can't both go", async () => {
    const { db, rota } = await setup({ "icu-night": ["dr-adeyemi", "dr-brandt"] });
    const results = await Promise.all([rota.leave("icu-night", "dr-adeyemi", now), rota.leave("icu-night", "dr-brandt", now)]);
    const report = await coverageReport(db, ["icu-night"]);
    console.log("leave results:", results, "still on call:", report[0].onCall);
    assert.deepEqual([...results].sort(), ["left", "refused_last_cover"]);
    assert.equal(report[0].onCall.length, 1);
});

test("when a whole team asks to leave at once, exactly one doctor stays", async () => {
    const { db, rota } = await setup({ "er-night": ["dr-a", "dr-b", "dr-c", "dr-d"] });
    const results = await Promise.all(["dr-a", "dr-b", "dr-c", "dr-d"].map((d) => rota.leave("er-night", d, now)));
    assert.equal(results.filter((r) => r === "left").length, 3);
    assert.equal((await coverageReport(db, ["er-night"]))[0].onCall.length, 1);
});

test("concurrent leave requests across wards never leave a shift uncovered", async () => {
    const { db, rota } = await setup({ "icu-night": ["dr-a", "dr-b"], "peds-night": ["dr-c", "dr-d"], "er-night": ["dr-e", "dr-f", "dr-g"] });
    await Promise.all([
        rota.leave("icu-night", "dr-a", now),
        rota.leave("icu-night", "dr-b", now),
        rota.leave("peds-night", "dr-c", now),
        rota.leave("peds-night", "dr-d", now),
        rota.leave("er-night", "dr-e", now),
    ]);
    assert.deepEqual(uncovered(await coverageReport(db, ["icu-night", "peds-night", "er-night"])), []);
});

test("leaving different shifts at the same time doesn't cause retries", async () => {
    const { db, rota } = await setup({ "icu-night": ["dr-a", "dr-b"], "peds-night": ["dr-c", "dr-d"] });
    const before = db.attempts;
    await Promise.all([rota.leave("icu-night", "dr-a", now), rota.leave("peds-night", "dr-c", now)]);
    assert.equal(db.attempts - before, 2);
});

test("a handover keeps the shift covered, and leaving when not on call is an error", async () => {
    const { db, rota } = await setup({ "icu-night": ["dr-adeyemi"] });
    await rota.handOver("icu-night", "dr-adeyemi", "dr-cho", now);
    assert.deepEqual((await coverageReport(db, ["icu-night"]))[0].onCall, ["dr-cho"]);
    await assert.rejects(rota.leave("icu-night", "dr-adeyemi", now), /not on call/);
});
